    fun list(scene: String): List<Dhikr> = scenes[scene].orEmpty()

    /** اختيار ثابت خلال اليوم الواحد ومتغيّر من يوم لآخر. */
    fun pick(scene: String, seed: Long): Dhikr? {
        val l = list(scene)
        if (l.isEmpty()) return null
        val i = (((seed % l.size) + l.size) % l.size).toInt()
        return l[i]
    }
